<script setup>
import { computed,ref,watch } from 'vue';import { api,saveDownload } from '../api';import { session } from '../session'
const operator=computed(()=>session.user?.role==='operator'),type=ref('products'),file=ref(null),inspection=ref(null),mapping=ref({}),sheet=ref(''),result=ref(null),error=ref(''),busy=ref(false),resolutions=ref({}),page=ref(1)
async function action(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
function form(){const body=new FormData();body.append('file',file.value);if(sheet.value)body.append('sheet_name',sheet.value);return body}
async function choose(value){if(!value)return;file.value=value;inspection.value=null;result.value=null;mapping.value={};resolutions.value={};if(!/\.(xlsx|csv)$/i.test(value.name)||value.size>5*1024*1024){error.value='请选择不超过 5 MB 的 CSV 或 XLSX';file.value=null;return}await action(async()=>{inspection.value=await api.request('/imports/inspect',{method:'POST',body:form()});sheet.value=inspection.value.sheet_name||'';for(const header of inspection.value.headers)mapping.value[header]=inspection.value.fields[type.value].includes(header)?header:''})}
async function preview(){await action(async()=>{const body=form();body.append('import_type',type.value);body.append('field_mapping',JSON.stringify(Object.fromEntries(Object.entries(mapping.value).filter(([_k,v])=>v))));result.value=await api.request('/imports/preview',{method:'POST',body});page.value=1;resolutions.value={}})}
async function loadPage(next){await action(async()=>{result.value=await api.request(`/imports/${result.value.id}?page=${next}&page_size=50`);page.value=next})}
async function commit(){await action(async()=>{await api.request(`/imports/${result.value.id}/commit`,{method:'POST',body:{row_resolutions:resolutions.value}});result.value=await api.request(`/imports/${result.value.id}`);page.value=1})}
async function exportErrors(){await action(async()=>{let rows=[];for(let p=1;p<=Math.ceil(result.value.rows.total/200);p++){const batch=await api.request(`/imports/${result.value.id}?page=${p}&page_size=200`);rows.push(...batch.rows.items.filter(x=>x.validation_status==='invalid'||x.commit_status==='failed'))}const escape=value=>'"'+String(value??'').replaceAll('"','""')+'"';const text='\ufeff'+[['row_number','normalized_data','errors'],...rows.map(x=>[x.row_number,JSON.stringify(x.normalized_data),x.details.map(d=>d.message).join('; ')])].map(r=>r.map(escape).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`import-${result.value.id}-errors.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
watch(type,()=>{result.value=null;if(inspection.value)for(const h of inspection.value.headers)mapping.value[h]=inspection.value.fields[type.value].includes(h)?h:''})
</script>
<template><section class="page"><div class="eyebrow">DATA CENTER</div><h2>批量导入与数据中心</h2><p>Excel/CSV → 字段映射 → 后端预览 → 重复行选择 → 确认写入。错误行保留，其他有效行分别提交。</p><p v-if="error" class="error" role="alert">{{error}}</p><section class="panel stack"><div class="toolbar"><label>数据类型<select v-model="type" :disabled="busy"><option value="products">商品信息</option><option value="inventory">SKU 库存</option><option value="competitors">竞品资料</option><option value="metrics">经营数据</option></select></label><button v-for="format in ['csv','xlsx']" :key="format" class="ghost" :disabled="busy" @click="action(()=>saveDownload(`/imports/templates/${type}?format=${format}`,`${type}.${format}`))">下载 {{format.toUpperCase()}} 模板</button></div><p v-if="type==='metrics'">实验编码填写工作台显示的 EXP-编号，日期须属于已批准实验周期；指标由原始数据计算。</p><template v-if="operator"><div class="drop-zone" @dragover.prevent @drop.prevent="choose($event.dataTransfer.files[0])"><label>拖拽 Excel/CSV 到此处，或选择文件<input type="file" accept=".csv,.xlsx" :disabled="busy" @change="choose($event.target.files[0])"></label><p v-if="file">{{file.name}} · {{(file.size/1024).toFixed(1)}} KB</p></div><div v-if="inspection"><label v-if="inspection.sheets.length">工作表<select v-model="sheet" @change="choose(file)"><option v-for="s in inspection.sheets" :key="s">{{s}}</option></select></label><p>文件包含 {{inspection.row_count}} 行；请核对表头映射。</p><div class="form-grid"><label v-for="h in inspection.headers" :key="h">{{h}} →<select v-model="mapping[h]"><option value="">保持原表头／忽略非模板字段</option><option v-for="field in inspection.fields[type]" :key="field">{{field}}</option></select></label></div><button class="primary" :disabled="busy" @click="preview">后端校验并预览</button></div></template><p v-else>主管可下载模板、查看工作台经营结果；上传与确认导入由运营操作。</p></section><section v-if="result" class="panel stack"><h3>批次 #{{result.id}} · {{result.status}}</h3><div class="toolbar"><span v-for="(value,key) in result.summary" :key="key">{{key}}：{{value}}</span></div><p>数据库重复选择“更新”或“跳过”；文件内重复只能保留一行，其余跳过。不同分页中的选择会保留。</p><div class="table-scroll"><table><thead><tr><th>原行号</th><th>预览结果</th><th>数据</th><th>问题</th><th>处理选择／提交结果</th></tr></thead><tbody><tr v-for="row in result.rows.items" :key="row.row_number" :class="row.validation_status==='invalid'?'invalid-row':''"><td>{{row.row_number}}</td><td>{{row.validation_status}}</td><td><dl><template v-for="(value,key) in row.normalized_data" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></template></dl></td><td>{{row.details.map(x=>x.message).join('；')}}</td><td><select v-if="result.status==='previewed'&&row.validation_status==='duplicate'" v-model="resolutions[row.row_number]"><option :value="undefined">请选择</option><option value="skip">跳过</option><option v-if="!row.existing_resource_id" value="keep">保留并新增</option><option v-if="row.existing_resource_id" value="update">更新已有记录</option></select><span v-else>{{row.commit_status||'有效新行自动新增'}}</span></td></tr></tbody></table></div><div class="toolbar"><button class="ghost" :disabled="busy||page===1" @click="loadPage(page-1)">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(result.rows.total/50))}}</span><button class="ghost" :disabled="busy||page*50>=result.rows.total" @click="loadPage(page+1)">下一页</button><button v-if="operator&&result.status==='previewed'" class="primary" :disabled="busy" @click="commit">确认导入有效行</button><button class="ghost" :disabled="busy" @click="exportErrors">导出全部错误明细</button><button v-if="result.status==='committing'" class="ghost" :disabled="busy" @click="loadPage(page)">查询提交状态</button></div></section></section></template>
